```ts
export class JobQueue {
  private active = 0;
  private waiting: (() => void)[] = [];
  private idle: (() => void)[] = [];

  constructor(
    private readonly concurrency: number,
    private readonly retries = 3,
  ) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
  }

  /** Resolves with the job's result, or rejects with its last error once retries are exhausted. */
  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.waiting.push(async () => {
        try {
          resolve(await this.attempt(job));
        } catch (err) {
          reject(err);
        } finally {
          this.active--;
          this.next();
        }
      });
      this.next();
    });
  }

  /** Resolves when nothing is running or waiting, whether jobs succeeded or failed. */
  onIdle(): Promise<void> {
    if (this.active === 0 && this.waiting.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.idle.push(resolve));
  }

  private next(): void {
    while (this.active < this.concurrency && this.waiting.length > 0) {
      this.active++;
      this.waiting.shift()!();
    }
    if (this.active === 0 && this.waiting.length === 0) {
      for (const resolve of this.idle.splice(0)) resolve();
    }
  }

  private async attempt<T>(job: () => Promise<T>): Promise<T> {
    // chisle: immediate retry; add backoff if jobs hit rate-limited services
    for (let i = 0; ; i++) {
      try {
        return await job();
      } catch (err) {
        if (i >= this.retries) throw err;
      }
    }
  }
}
