import assert from "node:assert/strict";

const q = new JobQueue(2);
let running = 0, peak = 0, attempts = 0;
const work = async () => {
  peak = Math.max(peak, ++running);
  await new Promise((r) => setTimeout(r, 10));
  running--;
};
for (let i = 0; i < 5; i++) q.add(work);
q.add(async () => { if (++attempts < 4) throw new Error("flaky"); });
const failed = q.add(async () => { throw new Error("always"); }).catch((e) => e.message);

await q.onIdle();
assert.equal(peak, 2);
assert.equal(attempts, 4);
assert.equal(await failed, "always");
```

- **Attempts:** "retries up to three times" is implemented as 1 initial attempt + 3 retries, so 4 attempts in total.
- **Rejections:** `add()` rejects when a job fails for good, so handle or `.catch` each returned promise, or Node reports an unhandled rejection.
- **Skipped:** backoff, per-job timeout and cancellation; add them when jobs call flaky or rate-limited services.

