function decodeCursor(cursor) {
  try {
    const [ts, id] = JSON.parse(Buffer.from(cursor, "base64url").toString());
    if (typeof ts === "string" && typeof id === "string") return [ts, id];
  } catch {}
  return null;
}

router.get("/orders", async (req, res, next) => {
  const limit = req.query.limit === undefined ? 20 : Number(req.query.limit);
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
    return res.status(400).json({ error: `limit must be an integer between 1 and ${MAX_LIMIT}` });
  }

  let after = null;
  if (req.query.cursor !== undefined) {
    after = typeof req.query.cursor === "string" ? decodeCursor(req.query.cursor) : null;
    if (!after) return res.status(400).json({ error: "invalid cursor" });
  }

  const where = after ? "WHERE (created_at, id) < ($1::timestamptz, $2)" : "";
  const params = after ? [...after, limit + 1] : [limit + 1];

  try {
    // created_at::text keeps microseconds; a JS Date would truncate to ms and skip or repeat rows
    const { rows } = await pool.query(
      `SELECT id, customer_id, status, total, created_at, created_at::text AS cursor_ts
         FROM orders
         ${where}
        ORDER BY created_at DESC, id DESC
        LIMIT $${params.length}`,
      params,
    );

    // one extra row fetched to know whether another page exists
    const page = rows.slice(0, limit);
    const nextCursor = rows.length > limit ? encodeCursor(page[page.length - 1]) : null;
    res.json({ data: page.map(({ cursor_ts, ...order }) => order), nextCursor });
  } catch (err) {
    // class 22 = data exception: the cursor decoded but held a bad timestamp or id
    if (after && err.code?.startsWith("22")) return res.status(400).json({ error: "invalid cursor" });
    next(err);
  }
});

module.exports = router;
